CREATE OR REPLACE FUNCTION private.cancel_pending_matches_for_removed_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id text := case when tg_op = 'DELETE' then old.id else new.id end;
  v_inactive boolean := tg_op = 'DELETE';
begin
  if tg_table_name = 'transactions' and tg_op <> 'DELETE' then
    v_inactive := new.removed_at is not null or new.deleted_at is not null;
    if new.match_reason = 'replaced_by_posted_transaction' then return new; end if;
  end if;
  if not v_inactive then return new; end if;

  update public.pending_plan_matches
  set status = 'cancelled', updated_at = now()
  where target_type = case when tg_table_name = 'transactions' then 'manual' else 'bill' end
    and target_id = v_id
    and status in ('active', 'ready_review');
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.household_activity_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  source_row jsonb;
  previous_row jsonb;
  target_household uuid;
  actor_id uuid;
  action_name text;
  item_id text;
  item_label text;
begin
  if tg_op = 'DELETE' then
    source_row := to_jsonb(old);
    action_name := 'deleted';
  elsif tg_op = 'INSERT' then
    source_row := to_jsonb(new);
    action_name := 'created';
  else
    source_row := to_jsonb(new);
    previous_row := to_jsonb(old);
    action_name := 'updated';

    -- Timestamp/review heartbeats are maintenance, not household edits.
    if (
      source_row - array[
        'updated_at',
        'last_reviewed_at',
        'synced_at',
        'last_synced_at',
        'last_reconciled_at',
        'provider_updated_at'
      ]
    ) = (
      previous_row - array[
        'updated_at',
        'last_reviewed_at',
        'synced_at',
        'last_synced_at',
        'last_reconciled_at',
        'provider_updated_at'
      ]
    ) then
      return new;
    end if;
  end if;

  if nullif(source_row->>'household_id', '') is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  -- Never credit a background/service update to the user who originally
  -- created the row. Only an authenticated member can appear as the actor.
  actor_id := auth.uid();
  if actor_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  target_household := (source_row->>'household_id')::uuid;
  item_id := coalesce(source_row->>'id', source_row->>'bill_id', source_row->>'account_id', source_row->>'user_id');
  item_label := coalesce(
    source_row->>'name',
    nullif(source_row->>'note', ''),
    nullif(source_row->>'category', ''),
    initcap(replace(tg_table_name, '_', ' '))
  );

  if tg_table_name = 'monthly_overrides' then
    item_label := 'Monthly bill update';
  elsif tg_table_name = 'extra_payments' then
    item_label := 'Debt snowball payment';
  elsif tg_table_name = 'bill_date_moves' then
    item_label := 'Bill date move';
  elsif tg_table_name = 'account_balances' then
    item_label := 'Account balance';
  end if;

  -- Creating an item can be followed by an initialization update in the
  -- same user action. Keep the creation as the single visible activity.
  if action_name = 'updated'
     and item_id is not null
     and exists (
       select 1
       from public.household_activity a
       where a.household_id = target_household
         and a.actor_user_id = actor_id
         and a.action = 'created'
         and a.entity_type = tg_table_name
         and a.entity_id = item_id
         and a.created_at >= clock_timestamp() - interval '2 minutes'
     ) then
    return new;
  end if;

  perform public.log_household_activity(
    target_household,
    action_name,
    tg_table_name,
    item_id,
    item_label,
    actor_id
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_bucket_budget_edit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 -- Existing overspent buckets must remain reopenable and repairable.
 if old.goal_type='planned_expense' and new.target_amount is distinct from old.target_amount
  and new.target_amount+0.005<old.current_amount then raise exception 'The bucket budget must cover its existing purchases'; end if;
 if current_user not in ('postgres','service_role','supabase_admin') and old.goal_type='planned_expense'
  and (new.current_amount is distinct from old.current_amount or new.goal_type is distinct from old.goal_type) then
  raise exception 'Bucket spending changed. Refresh before editing this budget';
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_routed_bucket_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE'
     and current_user = 'postgres'
     and current_setting('flowledger.shared_plan_owner_transfer', true) = 'on'
     and new.user_id is distinct from old.user_id
     and row(
       new.id, new.name, new.target_amount, new.target_date, new.goal_type,
       new.household_id, new.budget_id, new.current_amount,
       new.closed_at, new.closed_by, new.archived_at, new.archived_by,
       new.created_at
      ) is not distinct from row(
       old.id, old.name, old.target_amount, old.target_date, old.goal_type,
       old.household_id, old.budget_id, old.current_amount,
       old.closed_at, old.closed_by, old.archived_at, old.archived_by,
       old.created_at
     )
     and exists (
       select 1 from public.household_members member
       where member.household_id = old.household_id
         and member.user_id = new.user_id
     ) then
    return new;
  end if;

  if exists (
      select 1 from public.extra_payments payment
      where payment.household_id is not distinct from old.household_id
        and payment.budget_id is not distinct from old.budget_id
        and exists (
          select 1 from jsonb_array_elements(coalesce(payment.sources, '[]'::jsonb)) source
          where source ->> 'type' = 'bucket_remainder'
            and source ->> 'bucketId' = old.id
        )
    ) then
    if tg_op = 'DELETE' then
      raise exception 'Reopen and unroute this spending bucket before deleting it';
    end if;
    if row(
      new.name, new.target_amount, new.target_date, new.goal_type,
      new.user_id, new.household_id, new.budget_id,
      new.current_amount, new.closed_at, new.closed_by, new.archived_at, new.archived_by
    ) is distinct from row(
      old.name, old.target_amount, old.target_date, old.goal_type,
      old.user_id, old.household_id, old.budget_id,
      old.current_amount, old.closed_at, old.closed_by, old.archived_at, old.archived_by
    ) then
      raise exception 'Reopen and unroute this spending bucket before changing it';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

